  example_vi,
  word_audio_url,
  sentence_audio_url
) as (
  values
    ('冷酷', '他的冷酷态度让同事们感到难以接近。', 'lạnh lùng', 'lěng kù', '他的冷酷态度让同事们感到难以接近。', 'lạnh lùng', 'lěng kù', 'Tā de lěngkù tàidù ràng tóngshìmen gǎndào nányǐ jiējìn.', 'Thái độ lạnh lùng của anh ta khiến đồng nghiệp cảm thấy khó gần.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-33f434c1ab63f1e425159e4d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-078351f8d6f87dbb8bb71542.mp3'),
    ('冷落', '节假日期间这家店显得十分冷落，顾客很少。', 'ghẻ lạnh, lạnh nhạt, vắng vẻ', 'lěng luò', '节假日期间这家店显得十分冷落，顾客很少。', 'ghẻ lạnh, lạnh nhạt, vắng vẻ', 'lěng luò', 'Jiéjiàrì qījiān zhè jiā diàn xiǎnde shífēn lěngluò, gùkè hěn shǎo.', 'Trong kỳ nghỉ lễ, cửa hàng này trông rất vắng vẻ, khách rất ít.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-751fab6d3bf8bc5f279108c8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-1fdf5fb8dcc4a5e53bd27767.mp3'),
    ('冷却', '机械停止运转后，设备需要一段时间冷却。', 'làm lạnh', 'lěng què', '机械停止运转后，设备需要一段时间冷却。', 'làm lạnh', 'lěng què', 'Jīxiè tíngzhǐ yùnzhuǎn hòu, shèbèi xūyào yí duàn shíjiān lěngquè.', 'Sau khi máy móc dừng hoạt động, thiết bị cần có thời gian để làm lạnh.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6cac16b39789379a25157f3b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e0ce388571047d284ab9c984.mp3'),
    ('例外', '在这次考试中，他是唯一的例外，成绩没有及格。', 'ngoại lệ', 'lì wài', '在这次考试中，他是唯一的例外，成绩没有及格。', 'ngoại lệ', 'lì wài', 'Zài zhè cì kǎoshì zhōng, tā shì wéiyī de lìwài, chéngjī méiyǒu jígé.', 'Trong kỳ thi này, anh ấy là ngoại lệ duy nhất, điểm số không đạt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-794a49d557731929f86bb610.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-002d0209762b745b2e897e51.mp3'),
    ('伶俐', '小孩子非常伶俐，能很快学会新知识。', 'lanh lợi', 'líng lì', '小孩子非常伶俐，能很快学会新知识。', 'lanh lợi', 'líng lì', 'Xiǎo háizi fēicháng línglì, néng hěn kuài xuéhuì xīn zhīshì.', 'Đứa trẻ rất lanh lợi, có thể học kiến thức mới rất nhanh.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-edc94d4a210140d5e3d698b1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-abd6d4ea007171b545024ab1.mp3'),
    ('乐趣', '阅读是她生活中最大的乐趣之一。', 'niềm vui', 'lè qù', '阅读是她生活中最大的乐趣之一。', 'niềm vui', 'lè qù', 'Yuèdú shì tā shēnghuó zhōng zuìdà de lèqù zhī yī.', 'Đọc sách là một trong những niềm vui lớn nhất trong cuộc sống của cô ấy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6e6fbfd671f2ce4291050bbd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-1b8773c69ec4c97e1c5c4d7f.mp3'),
    ('乐意', '如果你需要帮助，我乐意随时为你效劳。', 'cam tâm tình nguyện làm việc gì đó', 'lè yì', '如果你需要帮助，我乐意随时为你效劳。', 'cam tâm tình nguyện làm việc gì đó', 'lè yì', 'Rúguǒ nǐ xūyào bāngzhù, wǒ lèyì suíshí wèi nǐ xiàoláo.', 'Nếu bạn cần giúp đỡ, tôi cam tâm tình nguyện phục vụ bạn bất cứ lúc nào.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-ee17a376a25dc6351c95fcbd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-9a92482a75135ea72fd7c303.mp3'),
    ('临床', '医生在临床实践中积累了丰富的经验。', 'lâm sàng', 'lín chuáng', '医生在临床实践中积累了丰富的经验。', 'lâm sàng', 'lín chuáng', 'Yīshēng zài línchuáng shíjiàn zhōng jīlěi le fēngfù de jīngyàn.', 'Bác sĩ đã tích lũy được nhiều kinh nghiệm phong phú trong thực hành lâm sàng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-f4381033a76316ad265e4e8a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-cca80602ff039e8de3f16399.mp3'),
    ('默默', '他默默地支持着团队，却很少表现自己。', 'lặng thầm', 'mò mò', '他默默地支持着团队，却很少表现自己。', 'lặng thầm', 'mò mò', 'Tā mòmò de zhīchí zhe tuánduì, què hěn shǎo biǎoxiàn zìjǐ.', 'Anh ấy âm thầm ủng hộ đội nhóm, nhưng rất ít khi thể hiện bản thân.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-810bc624036a1f37e455a230.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-fe0e96f2b5eca2f440257db3.mp3'),
    ('麻醉', '手术前，患者接受了全身麻醉。', 'gây tê', 'má zuì', '手术前，患者接受了全身麻醉。', 'gây tê', 'má zuì', 'Shǒushù qián, huànzhě jiēshòu le quánshēn mázuì.', 'Trước ca phẫu thuật, bệnh nhân đã được gây tê toàn thân.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-ae2da75926062d04450303e0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-0b7d933b3a0a68ab0dd6098e.mp3'),
