    ('偏偏', '我明明告诉他不要去，偏偏他还是坚持自己的决定。', 'cố ý, lại', 'piān piān', '我明明告诉他不要去，偏偏他还是坚持自己的决定。', 'cố ý, lại', 'piān piān', 'Wǒ míngmíng gàosu tā bùyào qù, piānpiān tā háishì jiānchí zìjǐ de juédìng.', 'Tôi rõ ràng bảo anh ấy đừng đi, nhưng anh ấy lại cố ý vẫn giữ quyết định của mình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6546d666436c3c74cee08bbb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-cfa3e3097fda3afdf26e601b.mp3'),
    ('齐心协力', '只有齐心协力，我们才能克服困难，实现目标。', 'đồng tâm hiệp lực', 'qí xīn xié lì', '只有齐心协力，我们才能克服困难，实现目标。', 'đồng tâm hiệp lực', 'qí xīn xié lì', 'Zhǐyǒu qíxīn xiélì, wǒmen cáinéng kèfú kùnnán, shíxiàn mùbiāo.', 'Chỉ khi đồng tâm hiệp lực, chúng ta mới có thể vượt qua khó khăn và đạt được mục tiêu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-95ed87cc64246af92a21f742.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-2a4235c67ec84111a657e1f9.mp3'),
    ('齐全', '这家超市的商品种类齐全，什么都可以买到。', 'đầy đủ', 'qí quán', '这家超市的商品种类齐全，什么都可以买到。', 'đầy đủ', 'qí quán', 'Zhè jiā chāoshì de shāngpǐn zhǒnglèi qíquán, shénme dōu kěyǐ mǎidào.', 'Siêu thị này có đầy đủ các loại hàng hóa, cái gì cũng có thể mua được.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7278c3fe5544d795f47d04c9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e5970d473d77b0724015897d.mp3'),
    ('驱逐', '政府决定驱逐所有非法居留的外国人。', 'trục xuất', 'qū zhú', '政府决定驱逐所有非法居留的外国人。', 'trục xuất', 'qū zhú', 'Zhèngfǔ juédìng qūzhú suǒyǒu fēifǎ jūliú de wàiguó rén.', 'Chính phủ quyết định trục xuất tất cả người nước ngoài ở lại bất hợp pháp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0381ac59232e807672317106.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-6aee9007d655392556447884.mp3'),
    ('锲而不舍', '他在学习上锲而不舍，最终取得了优异的成绩。', 'miệt mài, kiên nhẫn', 'qiè ér bù shě', '他在学习上锲而不舍，最终取得了优异的成绩。', 'miệt mài, kiên nhẫn', 'qiè ér bù shě', 'Tā zài xuéxí shàng qiè ér bù shě, zuìzhōng qǔdé le yōuyì de chéngjì.', 'Anh ấy kiên trì không bỏ cuộc trong học tập, cuối cùng đạt được kết quả xuất sắc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-ae62ee5c893f772090d662c4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-43e8c9e16a90e7f39e064afd.mp3'),
    ('钦佩', '我非常钦佩她面对困难时的坚强和勇气。', 'khâm phục', 'qīn pèi', '我非常钦佩她面对困难时的坚强和勇气。', 'khâm phục', 'qīn pèi', 'Wǒ fēicháng qīnpèi tā miàn duì kùnnán shí de jiānqiáng hé yǒngqì.', 'Tôi rất khâm phục sự mạnh mẽ và dũng cảm của cô ấy khi đối mặt với khó khăn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-ef0568f62b4acfaf63d2416d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-1112bde80258bc027c118ea6.mp3')
)
update public.cards as card
set
  pinyin = case
    when card.pinyin = repaired.original_pinyin then repaired.pinyin
    else card.pinyin
  end,
  meaning_vi = case
    when card.meaning_vi = repaired.original_meaning_vi then repaired.meaning_vi
    else card.meaning_vi
  end,
  example_cn = repaired.example_cn,
  example_pinyin = repaired.example_pinyin,
  example_vi = repaired.example_vi,
  word_audio_url = repaired.word_audio_url,
  sentence_audio_url = repaired.sentence_audio_url
from public.decks as deck,
  repaired_hsk as repaired
where card.deck_id = deck.id
  and card.user_id = deck.user_id
  and (
    deck.source_template_slug = 'hsk6-co-ban'
    or (
      deck.source_template_slug is null
      and deck.name = 'HSK6 cơ bản'
    )
  )
  and card.chinese = repaired.chinese
  and (
    card.example_cn is not distinct from repaired.original_example_cn
    or card.example_cn is null
  );
